import java.sql.*;import java.nio.file.*;import java.util.*;import java.lang.management.*;import java.security.*;import java.lang.reflect.*;import com.alibaba.fastjson2.*;import webridge.wbridge.storedprocedure.SPConfig;import webridge.wbridge.storedprocedure.invocation.SPInvokeManager;
/** One frozen workload plan per fresh fixture, retaining mutations through warmup/measurement. */
public class LittleXTiming {
 static JSONObject input;static JSONObject bundle;static boolean sp,active,hit;static String api;static JSONArray regions=new JSONArray();static JSONObject currentRegion;
 static Map<String,Long>status(Connection c)throws Exception{Map<String,Long>x=new TreeMap<>();try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SHOW SESSION STATUS WHERE Variable_name IN('Questions','Queries','Com_call_procedure','Com_select','Com_begin','Com_commit')")){while(r.next())x.put(r.getString(1),r.getLong(2));}return x;}
 static Object canonical(Object x){if(x instanceof Map){TreeMap<String,Object>m=new TreeMap<>();for(Object key:((Map)x).keySet()){String k=(String)key;if(Arrays.asList("_jac_id","id","jid","created_at","server_total_ms","server_commit_ms","server_ms").contains(k))continue;m.put(k,canonical(((Map)x).get(k)));}return m;}if(x instanceof List){List<Object>a=new ArrayList<>();for(Object e:(List)x)a.add(canonical(e));return a;}return x;}
 static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();}
 public static void main(String[]a)throws Exception{
 Path plan=Paths.get(a[0]),out=Paths.get(a[1]);Files.createDirectories(out);sp=a[2].equals("sp");JSONArray rows=JSON.parseArray(new String(Files.readAllBytes(plan),"UTF-8"));String impl=System.getProperty("littlex.implementation","LittleXSql");Class<?> clazz=Class.forName(impl);Method request=clazz.getMethod("request",Connection.class,JSONObject.class);
 if(sp){Path home=Paths.get(a[3]);bundle=JSON.parseObject(new String(Files.readAllBytes(home.resolve("metadata.json")),"UTF-8"));SPConfig.addConfig(home.resolve("aligned.conf").toFile());System.setProperty("spDefDir",home.resolve("generated/sql").toString());}
 clazz.getField("boundary").set(null,new LittleXSql.Boundary(){public void enter(Connection c)throws Exception{if(sp){String key=input.getString("op");try{String r=(String)clazz.getField("region").get(null);if(r!=null)key=r;}catch(NoSuchFieldException ignored){}api=bundle.getJSONObject("operations").getString(key);currentRegion=LittleXSql.obj("region",key,"api",api,"source_calls_before",clazz.getField("commands").getLong(null));regions.add(currentRegion);if(api==null){currentRegion.put("execution","source fallback: no compiled region");return;}SPInvokeManager.beginApi(api);active=true;SPInvokeManager.setInvokingSp(true);for(String k:input.keySet()){Object v=input.get(k);if(v instanceof String){SPInvokeManager.storeParam("REQUEST_PARAM_"+k,v);SPInvokeManager.storeParam("M_L_String__REQUEST_PARAM_"+k,v);}}}}public void leave(Connection c)throws Exception{if(active){hit=SPInvokeManager.isInvokingSp();currentRegion.put("sp_enabled_at_end",hit);currentRegion.put("source_calls",clazz.getField("commands").getLong(null)-currentRegion.getLongValue("source_calls_before"));SPInvokeManager.endApi();active=false;}}});
 ThreadMXBean cpu=ManagementFactory.getThreadMXBean();if(cpu.isCurrentThreadCpuTimeSupported()&&!cpu.isThreadCpuTimeEnabled())cpu.setThreadCpuTimeEnabled(true);
 try(Connection c=DriverManager.getConnection(System.getProperty("littlex.url"),"root","");java.io.BufferedWriter fullResults=new java.io.BufferedWriter(new java.io.OutputStreamWriter(new java.util.zip.GZIPOutputStream(Files.newOutputStream(out.resolve("full-results.jsonl.gz"))),"UTF-8"))){
 Files.write(out.resolve("connection-id.json"),("{\"connection_id\":"+c.getClass().getMethod("getId").invoke(c)+"}").getBytes("UTF-8"));
 for(int i=0;i<rows.size();i++){JSONObject item=rows.getJSONObject(i);input=item.getJSONObject("input");Map<String,Long>before=status(c);hit=false;regions=new JSONArray();long wall=System.currentTimeMillis();Files.write(out.resolve("request-active.json"),LittleXSql.obj("phase",sp?"sp":"baseline","iteration",i,"op",input.getString("op"),"start_wall_ms",wall).toJSONString().getBytes("UTF-8"));long t=System.nanoTime(),ct=cpu.getCurrentThreadCpuTime();JSONObject result=(JSONObject)request.invoke(null,c,input);double ms=(System.nanoTime()-t)/1e6,cpums=(cpu.getCurrentThreadCpuTime()-ct)/1e6;Files.delete(out.resolve("request-active.json"));Map<String,Long>after=status(c);Map<String,Long>delta=new TreeMap<>();for(String k:after.keySet())delta.put(k,after.get(k)-before.get(k));long count=after.get("Questions")-before.get("Questions")-1;JSONObject row=LittleXSql.obj("phase",sp?"sp":"baseline","implementation",impl,"op",input.getString("op"),"warmup",item.getBooleanValue("warmup"),"iteration",item.getIntValue("iteration"),"plan_ordinal",i,"ms",ms,"thread_cpu_ms",cpums,"questions",count,"source_calls",clazz.getField("commands").getLong(null),"status_delta",delta,"sp_enabled_at_end",hit,"regions",regions,"execution_mode",sp?(hit&&delta.get("Com_call_procedure")>0?"webridge":delta.get("Com_call_procedure")>0?"hybrid":"direct fallback"):"direct","canonical_result_sha256",hex(MessageDigest.getInstance("SHA-256").digest(JSON.toJSONString(canonical(result)).getBytes("UTF-8"))),"feed_count",result.containsKey("feed")?result.getJSONArray("feed").size():null);
 fullResults.write(LittleXSql.obj("plan_ordinal",i,"warmup",item.getBooleanValue("warmup"),"iteration",item.getIntValue("iteration"),"result",result).toJSONString());fullResults.newLine();if(!input.getString("op").startsWith("feed"))row.put("result",result);Files.write(out.resolve("rows.jsonl"),(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);
 if(!sp&&count!=clazz.getField("commands").getLong(null))throw new IllegalStateException("Independent command count mismatch");}
 }Files.write(out.resolve("complete.json"),"{\"complete\":true}".getBytes("UTF-8"));
 }
}
